using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Searches the web for information on a given query. Returns relevant search results.")]
string WebSearch(string query)
{
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
    var results = query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") && q.Contains("2026") =>
            """
            1. "Quantum Computing Reaches 10,000 Qubit Milestone in 2026" - TechReview
               Summary: Major quantum hardware vendors achieved 10,000+ logical qubits with error correction rates below 0.01%.
            2. "Practical Quantum Advantage Demonstrated in Drug Discovery" - Nature
               Summary: Pharmaceutical companies report 100x speedup in molecular simulations using fault-tolerant quantum computers.
            3. "Quantum-Classical Hybrid Systems Now Standard in Enterprise" - InfoWorld
               Summary: Cloud providers offer seamless quantum-classical workflows; adoption grows 300% year-over-year.
            """,
        var q when q.Contains("quantum") && q.Contains("error correction") =>
            """
            1. "Topological Qubits Solve Error Correction Challenge" - PhysicsToday
               Summary: New topological qubit architectures achieve error rates of 10^-8, enabling long-duration computations.
            2. "Surface Code Optimizations Reduce Overhead by 60%" - arXiv
               Summary: Algorithmic improvements in surface codes drastically reduce the physical-to-logical qubit ratio.
            """,
        var q when q.Contains("quantum") && q.Contains("application") =>
            """
            1. "Quantum Machine Learning Models Outperform Classical on Financial Forecasting" - QuantumWeekly
               Summary: Banks deploy quantum ML for risk analysis with measurable accuracy improvements.
            2. "Quantum Optimization Revolutionizes Supply Chain Logistics" - MIT Tech Review
               Summary: Companies report 40% cost reduction using quantum annealing for route optimization.
            """,
        _ =>
            $"""
            1. "Overview of {query}" - Wikipedia
               Summary: General information about {query} covering key developments and current state.
            2. "Latest Research on {query}" - ScienceDaily
               Summary: Recent studies reveal new insights and breakthroughs related to {query}.
            3. "Expert Analysis: The Future of {query}" - TechInsights
               Summary: Industry experts weigh in on upcoming trends and potential impact.
            """
    };

    return results;
}

[Description("Takes a note to remember important information found during research. Use this to record key findings.")]
string TakeNote(string note)
{
    Console.WriteLine($"  [Tool] Taking note: \"{note[..Math.Min(note.Length, 80)]}...\"");
    notes.Add(note);
    return $"Note recorded. You now have {notes.Count} note(s).";
}

// --- Agent Setup ---

Console.WriteLine("=== AI Research Agent ===\n");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
    ]
};

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "quantum computing breakthroughs in 2026";

Console.WriteLine($"Researching topic: \"{topic}\"\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research agent. Your job is to thoroughly research the given topic using the available tools.

        Follow this process:
        1. Search the web for information about the topic (perform 2-3 searches with different angles)
        2. Take notes on the most important findings from each search
        3. After gathering enough information, provide a comprehensive summary

        Always take notes before summarizing. Your final response should be a well-structured summary
        of your research findings with key points and conclusions.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("--- Agent Working ---\n");

var response = await client.GetChatResponseAsync(messages, chatOptions);

Console.WriteLine("\n--- Research Complete ---\n");
Console.WriteLine(response.Message.Text);

if (notes.Count > 0)
{
    Console.WriteLine("\n--- Notes Taken During Research ---");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"\n[{i + 1}] {notes[i]}");
    }
}

